/**
 * Root app component for the Task Management Dashboard.
 *
 * Sets up React Router for client-side navigation and wraps the app
 * in the AuthProvider for authentication state management.
 *
 * Routes:
 *   /          → Login page
 *   /register  → Register page
 *   /tasks     → Task list (placeholder for Sprint 2)
 *   /reminders → Reminders (placeholder for Sprint 3)
 *   /analytics → Analytics (placeholder for Sprint 3)
 *
 * Layout:
 *   Desktop (≥768px): Fixed left sidebar (~240px) for navigation.
 *   Mobile (<768px): Hamburger button opens slide-over drawer.
 */

import { useState } from 'react';
import { BrowserRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { AuthProvider, useAuth } from './hooks/useAuth';
import { Login } from './components/Login';
import { Register } from './components/Register';

/* -------------------------------------------------------------------------- */
/*  Navigation                                                                */
/* -------------------------------------------------------------------------- */

/**
 * Navigation component with sidebar (desktop) and hamburger menu (mobile).
 *
 * On desktop (≥768px), the sidebar is always visible as a fixed left panel.
 * On mobile (<768px), a hamburger button toggles a slide-over drawer.
 */
function Navigation() {
  const { isAuthenticated, logout } = useAuth();
  const location = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);

  const handleLogout = async () => {
    await logout();
  };

  const navItems = [
    { path: '/tasks', label: 'Tasks' },
    { path: '/reminders', label: 'Reminders' },
    { path: '/analytics', label: 'Analytics' },
  ];

  return (
    <>
      {/* Mobile hamburger button — visible only on <768px */}
      <button
        className="hamburger-btn"
        onClick={() => setMobileOpen(!mobileOpen)}
        aria-label="Toggle navigation"
        aria-expanded={mobileOpen}
      >
        <span className="hamburger-line" />
        <span className="hamburger-line" />
        <span className="hamburger-line" />
      </button>

      {/* Mobile overlay — dims the background when drawer is open */}
      <div
        className={`mobile-overlay ${mobileOpen ? 'mobile-overlay-active' : ''}`}
        onClick={() => setMobileOpen(false)}
        aria-hidden="true"
      />

      {/* Sidebar / slide-over drawer */}
      <nav
        className={`sidebar ${mobileOpen ? 'sidebar-open' : ''}`}
        aria-label="Main navigation"
      >
        <div className="sidebar-header">
          <h2 className="sidebar-title">Task Management</h2>
          <button
            className="sidebar-close"
            onClick={() => setMobileOpen(false)}
            aria-label="Close navigation"
          >
            &times;
          </button>
        </div>
        <ul className="sidebar-nav">
          {isAuthenticated ? (
            <>
              {navItems.map((item) => (
                <li key={item.path}>
                  <Link
                    to={item.path}
                    className={`nav-link ${location.pathname === item.path ? 'nav-link-active' : ''}`}
                    onClick={() => setMobileOpen(false)}
                  >
                    {item.label}
                  </Link>
                </li>
              ))}
              <li>
                <button
                  className="nav-link nav-link-logout"
                  onClick={handleLogout}
                >
                  Logout
                </button>
              </li>
            </>
          ) : (
            <>
              <li>
                <Link
                  to="/"
                  className={`nav-link ${location.pathname === '/' ? 'nav-link-active' : ''}`}
                  onClick={() => setMobileOpen(false)}
                >
                  Sign in
                </Link>
              </li>
              <li>
                <Link
                  to="/register"
                  className={`nav-link ${location.pathname === '/register' ? 'nav-link-active' : ''}`}
                  onClick={() => setMobileOpen(false)}
                >
                  Register
                </Link>
              </li>
            </>
          )}
        </ul>
      </nav>
    </>
  );
}

/* -------------------------------------------------------------------------- */
/*  Placeholder Pages                                                         */
/* -------------------------------------------------------------------------- */

function TasksPage() {
  return (
    <main>
      <h1>Tasks</h1>
      <p>Task list will be implemented in Sprint 2.</p>
    </main>
  );
}

function RemindersPage() {
  return (
    <main>
      <h1>Reminders</h1>
      <p>Reminders will be implemented in Sprint 3.</p>
    </main>
  );
}

function AnalyticsPage() {
  return (
    <main>
      <h1>Analytics</h1>
      <p>Analytics will be implemented in Sprint 3.</p>
    </main>
  );
}

/* -------------------------------------------------------------------------- */
/*  App Content                                                               */
/* -------------------------------------------------------------------------- */

/**
 * AppContent renders the layout shell with navigation and routes.
 * Must be inside BrowserRouter (and AuthProvider) to use hooks.
 */
function AppContent() {
  return (
    <div className="app-layout">
      <Navigation />
      <div className="app-main">
        <Routes>
          <Route path="/" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route path="/tasks" element={<TasksPage />} />
          <Route path="/reminders" element={<RemindersPage />} />
          <Route path="/analytics" element={<AnalyticsPage />} />
        </Routes>
      </div>
    </div>
  );
}

/**
 * Root app component.
 *
 * Wraps the app in BrowserRouter for client-side routing and
 * AuthProvider for authentication state.
 */
export function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <AppContent />
      </AuthProvider>
    </BrowserRouter>
  );
}

