/**
 * Acceptance tests for AC-1 (User registration and authentication)
 * and AC-8 (Users can register, login, logout securely).
 *
 * These tests verify:
 * - AC-1: A new user can register, then log in and receive a JWT access token
 * - AC-8: After logout, the same token cannot access protected endpoints (401)
 *
 * Each test creates uniquely-named records (via uniqueSuffix) so tests
 * don't interfere with each other on the shared service instance.
 */

import { test, expect } from '@playwright/test';
import { uniqueSuffix, registerUser, loginUser } from './helpers.js';

/**
 * [AC-1] User can register with unique credentials and receive 201
 *
 * Verifies that POST /api/register with valid data returns 201 Created
 * and the response body contains the expected user fields (id, username, email, created_at).
 * The test creates a user with a unique suffix to avoid conflicts with other tests.
 */
test('[AC-1] registration creates a new user', async ({ request }) => {
  const suffix = uniqueSuffix();
  const response = await registerUser(request, suffix);

  expect(response.status()).toBe(201);
  const body = await response.json();

  expect(body).toHaveProperty('id');
  expect(typeof body.id).toBe('number');
  expect(body).toHaveProperty('username', `testuser_${suffix}`);
  expect(body).toHaveProperty('email', `${suffix}@example.com`);
  expect(body).toHaveProperty('created_at');
  expect(typeof body.created_at).toBe('string');
});

/**
 * [AC-1] Registration rejects duplicate username
 *
 * Verifies that registering with an already-used username returns 409 Conflict
 * with the expected error message.
 */
test('[AC-1] registration rejects duplicate username', async ({ request }) => {
  const suffix = uniqueSuffix();
  const username = `dupuser_${suffix}`;
  const email = `first_${suffix}@example.com`;

  // First registration should succeed
  const firstResponse = await request.post('/api/register', {
    data: { username, email, password: 'SecurePass123!' },
  });
  expect(firstResponse.status()).toBe(201);

  // Second registration with same username should fail
  const secondResponse = await request.post('/api/register', {
    data: { username, email: `second_${suffix}@example.com`, password: 'SecurePass123!' },
  });
  expect(secondResponse.status()).toBe(409);
  const body = await secondResponse.json();
  expect(body.error).toBe('Username or email already exists');
});

/**
 * [AC-1] Registration rejects duplicate email
 *
 * Verifies that registering with an already-used email returns 409 Conflict.
 */
test('[AC-1] registration rejects duplicate email', async ({ request }) => {
  const suffix = uniqueSuffix();
  const email = `dupe_${suffix}@example.com`;
  const username = `first_${suffix}`;

  // First registration should succeed
  const firstResponse = await request.post('/api/register', {
    data: { username, email, password: 'SecurePass123!' },
  });
  expect(firstResponse.status()).toBe(201);

  // Second registration with same email should fail
  const secondResponse = await request.post('/api/register', {
    data: { username: `second_${suffix}`, email, password: 'SecurePass123!' },
  });
  expect(secondResponse.status()).toBe(409);
  const body = await secondResponse.json();
  expect(body.error).toBe('Username or email already exists');
});

/**
 * [AC-1] Login with valid credentials returns JWT access token
 *
 * Registers a user, then logs in with those credentials.
 * Asserts the response contains access_token (a JWT string) and token_type 'bearer'.
 */
test('[AC-1] login with valid credentials returns JWT token', async ({ request }) => {
  const suffix = uniqueSuffix();
  const email = `${suffix}@example.com`;
  const password = 'SecurePass123!';

  // Register first
  const registerResponse = await registerUser(request, suffix);
  expect(registerResponse.status()).toBe(201);

  // Now login
  const loginResponse = await request.post('/api/login', {
    data: { email, password },
  });
  expect(loginResponse.status()).toBe(200);
  const body = await loginResponse.json();

  expect(body).toHaveProperty('access_token');
  expect(typeof body.access_token).toBe('string');
  expect(body.access_token.length).toBeGreaterThan(0);
  // JWT tokens have three dot-separated parts
  expect(body.access_token.split('.').length).toBe(3);
  expect(body).toHaveProperty('token_type', 'bearer');

  // Login also sets a refresh_token cookie (AC-1)
  const setCookie = loginResponse.headers()['set-cookie'];
  expect(typeof setCookie).toBe('string');
  expect(setCookie).toContain('refresh_token=');
});

/**
 * [AC-1] Login with invalid credentials returns 401
 *
 * Verifies that logging in with wrong password returns 401 Unauthorized.
 */
test('[AC-1] login with invalid credentials returns 401', async ({ request }) => {
  const suffix = uniqueSuffix();
  const email = `${suffix}@example.com`;

  // Register a user
  await registerUser(request, suffix);

  // Login with wrong password
  const loginResponse = await request.post('/api/login', {
    data: { email, password: 'WrongPassword123!' },
  });
  expect(loginResponse.status()).toBe(401);
  const body = await loginResponse.json();
  expect(body.error).toBe('Invalid credentials');
});

/**
 * [AC-8] After logout, token cannot access protected endpoints
 *
 * Registers a user, logs in to get a token, calls logout, then attempts
 * to access /api/health (a protected endpoint) with the same token.
 * Asserts the response is 401 Unauthorized.
 */
test('[AC-8] logout invalidates the access token', async ({ request }) => {
  const suffix = uniqueSuffix();
  const email = `${suffix}@example.com`;
  const password = 'SecurePass123!';

  // Register and login
  const registerResponse = await registerUser(request, suffix);
  expect(registerResponse.status()).toBe(201);

  const loginResponse = await request.post('/api/login', {
    data: { email, password },
  });
  expect(loginResponse.status()).toBe(200);
  const loginBody = await loginResponse.json();
  const token = loginBody.access_token;

  // Logout
  const logoutResponse = await request.post('/api/logout', {
    headers: { Authorization: `Bearer ${token}` },
  });
  expect(logoutResponse.status()).toBe(200);
  const logoutBody = await logoutResponse.json();
  expect(logoutBody.message).toBe('Logged out successfully');

  // Now try to access a protected endpoint with the same token
  const protectedResponse = await request.get('/api/tasks', {
    headers: { Authorization: `Bearer ${token}` },
  });
  expect(protectedResponse.status()).toBe(401);
  const protectedBody = await protectedResponse.json();
  expect(protectedBody).toHaveProperty('error');
});

