"""Pydantic request/response schemas for the Task Management Dashboard API.

All schemas validate input at the API boundary and reject invalid data with
422 Validation Error responses.

Exports:
    UserCreate       – registration request body
    UserOut          – user profile response
    LoginRequest     – login request body
    LoginResponse    – login response (access token + type)
    RefreshResponse  – refresh response (access token + type)
    TaskCreate       – task creation request body
    TaskUpdate       – task update request body
    TaskOut          – single task response
    TaskAssigneeInput – assignee input for task creation/assignment
    TaskListResponse – paginated task list response
    ReminderCreate   – reminder creation request body
    ReminderOut      – single reminder response
    ReminderListResponse – reminders response (upcoming + due)
    AnalyticsResponse – analytics dashboard data
    ErrorDetail      – validation error detail for 422 responses
"""

import re
from datetime import date, datetime
from typing import Annotated, Any

from pydantic import BaseModel, EmailStr, Field, field_validator

# ---------------------------------------------------------------------------
# Auth schemas
# ---------------------------------------------------------------------------

_USERNAME_PATTERN = r"^\S+$"


class UserCreate(BaseModel):
    """Registration request body.

    Validates:
        username: 3-50 characters, no whitespace (pattern ^\\S+$)
        email: valid email format (Pydantic EmailStr)
        password: minimum 8 characters
    """

    username: Annotated[str, Field(min_length=3, max_length=50, pattern=_USERNAME_PATTERN)]
    email: Annotated[EmailStr, Field(max_length=255)]
    password: Annotated[str, Field(min_length=8)]

    model_config = {"extra": "forbid"}


class UserOut(BaseModel):
    """User profile response (no password_hash)."""

    id: int
    username: str
    email: str
    created_at: str

    model_config = {"from_attributes": True}


class LoginRequest(BaseModel):
    """Login request body.

    Both email and password are optional in the schema so that missing
    fields produce 401 (handled in the route handler) instead of 422.
    """

    email: str | None = None
    password: str | None = None

    model_config = {"extra": "forbid"}


class LoginResponse(BaseModel):
    """Login response – access token and token type only."""

    access_token: str
    token_type: str = "bearer"

    model_config = {"from_attributes": True}


class RefreshResponse(BaseModel):
    """Refresh response – new access token and token type only."""

    access_token: str
    token_type: str = "bearer"

    model_config = {"from_attributes": True}


# ---------------------------------------------------------------------------
# Task schemas
# ---------------------------------------------------------------------------

_PRIORITY_VALUES = ("low", "medium", "high", "urgent")
_STATUS_VALUES = ("pending", "in_progress", "completed", "cancelled")


class TaskAssigneeInput(BaseModel):
    """Input for assigning a user to a task."""

    user_id: int
    note: str | None = None

    model_config = {"from_attributes": True}


class TaskCreate(BaseModel):
    """Task creation request body.

    Validates:
        title: 3-200 characters
        priority: one of low/medium/high/urgent (default 'medium')
        status: one of pending/in_progress/completed/cancelled (default 'pending')
        categories: array of strings, each max 100 chars
        tags: array of strings, each max 100 chars
    """

    title: Annotated[str, Field(min_length=3, max_length=200)]
    description: str | None = None
    priority: str = "medium"
    due_date: str | None = None  # ISO 8601 date string
    status: str = "pending"
    categories: list[str] | None = None
    tags: list[str] | None = None
    assignees: list[TaskAssigneeInput] | None = None

    model_config = {"extra": "forbid"}

    @field_validator("priority")
    @classmethod
    def validate_priority(cls, v: str) -> str:
        if v not in _PRIORITY_VALUES:
            raise ValueError(f"priority must be one of {_PRIORITY_VALUES}")
        return v

    @field_validator("status")
    @classmethod
    def validate_status(cls, v: str) -> str:
        if v not in _STATUS_VALUES:
            raise ValueError(f"status must be one of {_STATUS_VALUES}")
        return v

    @field_validator("categories")
    @classmethod
    def validate_categories(cls, v: list[str] | None) -> list[str] | None:
        if v is not None:
            for item in v:
                if len(item) > 100:
                    raise ValueError("Each category value must be at most 100 characters")
        return v

    @field_validator("tags")
    @classmethod
    def validate_tags(cls, v: list[str] | None) -> list[str] | None:
        if v is not None:
            for item in v:
                if len(item) > 100:
                    raise ValueError("Each tag value must be at most 100 characters")
        return v


class TaskUpdate(BaseModel):
    """Task update request body (all fields optional).

    Only non-None fields are applied to the existing task.
    """

    title: str | None = Field(default=None, min_length=3, max_length=200)
    description: str | None = None
    priority: str | None = None
    due_date: str | None = None  # ISO 8601 date string
    status: str | None = None
    categories: list[str] | None = None
    tags: list[str] | None = None

    model_config = {"extra": "forbid"}

    @field_validator("priority")
    @classmethod
    def validate_priority(cls, v: str | None) -> str | None:
        if v is not None and v not in _PRIORITY_VALUES:
            raise ValueError(f"priority must be one of {_PRIORITY_VALUES}")
        return v

    @field_validator("status")
    @classmethod
    def validate_status(cls, v: str | None) -> str | None:
        if v is not None and v not in _STATUS_VALUES:
            raise ValueError(f"status must be one of {_STATUS_VALUES}")
        return v

    @field_validator("categories")
    @classmethod
    def validate_categories(cls, v: list[str] | None) -> list[str] | None:
        if v is not None:
            for item in v:
                if len(item) > 100:
                    raise ValueError("Each category value must be at most 100 characters")
        return v

    @field_validator("tags")
    @classmethod
    def validate_tags(cls, v: list[str] | None) -> list[str] | None:
        if v is not None:
            for item in v:
                if len(item) > 100:
                    raise ValueError("Each tag value must be at most 100 characters")
        return v


class TaskOut(BaseModel):
    """Single task response with owner and assignees."""

    id: int
    title: str
    description: str | None = None
    priority: str
    due_date: str | None = None
    status: str
    owner: dict[str, Any]
    assignees: list[dict[str, Any]]
    categories: list[str] | None = None
    tags: list[str] | None = None
    created_at: str
    updated_at: str
    completed_at: str | None = None

    model_config = {"from_attributes": True}


