/**
 * Authentication hook for the Task Management Dashboard.
 *
 * Provides authentication state (isAuthenticated, user, token) and methods
 * (login, register, logout, refresh). The hook attaches the Bearer token to
 * fetch requests and handles 401 responses by redirecting to login.
 *
 * Token storage:
 *   The access token is stored in a module-level ref (not localStorage)
 *   so it is not persistently stored on disk. The server-side session
 *   (via HTTP-only refresh_token cookie) handles persistence.
 *
 * Data flow:
 *   1. On mount, check for an existing refresh_token cookie.
 *   2. If present, attempt to refresh the access token.
 *   3. If refresh succeeds, the user is authenticated.
 *   4. If refresh fails, the user is redirected to login.
 */

import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useRef,
  type ReactNode,
} from 'react';

/* -------------------------------------------------------------------------- */
/*  Types                                                                     */
/* -------------------------------------------------------------------------- */

/** User object returned from the API's /register endpoint. */
export interface UserOut {
  id: number;
  username: string;
  email: string;
  created_at: string;
}

/** Shape of the /api/login response body. */
export interface LoginResponse {
  access_token: string;
  token_type: string;
}

/** Shape of the /api/refresh response body. */
export interface RefreshResponse {
  access_token: string;
  token_type: string;
}

/* -------------------------------------------------------------------------- */
/*  Helpers                                                                   */
/* -------------------------------------------------------------------------- */

/**
 * Read a cookie value by name.
 *
 * @param name - The cookie name to look for.
 * @returns The cookie value, or null if the cookie is not present.
 */
function getCookie(name: string): string | null {
  if (typeof document === 'undefined') return null;
  const match = document.cookie.match(
    new RegExp('(?:^|;\\s*)' + name + '=([^;]*)')
  );
  return match ? decodeURIComponent(match[1]) : null;
}

/* -------------------------------------------------------------------------- */
/*  Context                                                                   */
/* -------------------------------------------------------------------------- */

interface AuthContextValue {
  isAuthenticated: boolean;
  user: UserOut | null;
  token: string | null;
  login: (email: string, password: string) => Promise<void>;
  register: (username: string, email: string, password: string) => Promise<void>;
  logout: () => Promise<void>;
  refresh: () => Promise<boolean>;
}

const AuthContext = createContext<AuthContextValue | null>(null);

/**
 * Provide the auth context to a component tree.
 *
 * @param props - The React children to render inside the context provider.
 */
export function AuthProvider({ children }: { children: ReactNode }) {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [user, setUser] = useState<UserOut | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const tokenRef = useRef<string | null>(null);
  tokenRef.current = token;

  /* --- Refresh access token --- */
  const refresh = useCallback(async (): Promise<boolean> => {
    try {
      const response = await fetch('/api/refresh', { method: 'POST' });
      if (!response.ok) {
        throw new Error('Refresh failed');
      }
      const data: RefreshResponse = await response.json();
      setToken(data.access_token);
      tokenRef.current = data.access_token;
      return true;
    } catch {
      setToken(null);
      tokenRef.current = null;
      setIsAuthenticated(false);
      setUser(null);
      return false;
    }
  }, []);

  /* --- On mount: try to restore session from refresh token cookie --- */
  useEffect(() => {
    const rt = getCookie('refresh_token');
    if (rt) {
      refresh();
    }
  }, [refresh]);

  /* --- Login --- */
  const login = useCallback(
    async (email: string, password: string) => {
      const response = await fetch('/api/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      if (!response.ok) {
        const body = await response.json().catch(() => ({}));
        throw { status: response.status, body };
      }
      const data: LoginResponse = await response.json();
      setToken(data.access_token);
      tokenRef.current = data.access_token;
      setIsAuthenticated(true);
    },
    []
  );

  /* --- Register --- */
  const register = useCallback(
    async (username: string, email: string, password: string) => {
      const regResponse = await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, email, password }),
      });
      if (!regResponse.ok) {
        const body = await regResponse.json().catch(() => ({}));
        throw { status: regResponse.status, body };
      }
      // Auto-login after successful registration
      const loginResponse = await fetch('/api/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      if (!loginResponse.ok) {
        const body = await loginResponse.json().catch(() => ({}));
        throw { status: loginResponse.status, body };
      }
      const data: LoginResponse = await loginResponse.json();
      setToken(data.access_token);
      tokenRef.current = data.access_token;
      setIsAuthenticated(true);
    },
    []
  );

  /* --- Logout --- */
  const logout = useCallback(async () => {
    try {
      await fetch('/api/logout', {
        method: 'POST',
        headers: { Authorization: `Bearer ${tokenRef.current || ''}` },
      });
    } catch {
      // Ignore errors on logout — the token is cleared regardless
    }
    setToken(null);
    tokenRef.current = null;
    setIsAuthenticated(false);
    setUser(null);
  }, []);

  const value: AuthContextValue = {
    isAuthenticated,
    user,
    token,
    login,
    register,
    logout,
    refresh,
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

/**
 * Consume the auth context.
 *
 * @returns The auth context value with all methods and state.
 * @throws If called outside of an AuthProvider.
 */
export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return ctx;
}

