/**
 * Login page component.
 *
 * Renders a centered card with email and password inputs, a "Sign in" button,
 * and a link to create an account. Handles client-side validation and shows
 * inline error messages.
 *
 * On successful login, navigates to /tasks.
 */

import { useState, type FormEvent } from 'react';
import { useAuth } from '../hooks/useAuth';
import { useNavigate, Link } from 'react-router-dom';

export function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [emailError, setEmailError] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [generalError, setGeneralError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setEmailError('');
    setPasswordError('');
    setGeneralError('');

    let hasError = false;

    // Client-side validation
    if (!email.trim()) {
      setEmailError('Email is required');
      hasError = true;
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setEmailError('Invalid email format');
      hasError = true;
    }

    if (!password) {
      setPasswordError('Password is required');
      hasError = true;
    }

    if (hasError) return;

    setLoading(true);
    try {
      await login(email, password);
      navigate('/tasks');
    } catch (err: unknown) {
      if (err && typeof err === 'object' && 'status' in err) {
        const apiErr = err as { status: number };
        if (apiErr.status === 401) {
          setGeneralError('Invalid credentials');
        } else {
          setGeneralError('Network error — please try again');
        }
      } else {
        setGeneralError('Network error — please try again');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <main className="auth-page">
      <div className="auth-card">
        <h1 className="auth-title">Task Management Dashboard</h1>
        <form onSubmit={handleSubmit} noValidate>
          <div className="form-group">
            <label htmlFor="login-email">Email</label>
            <input
              id="login-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className={emailError ? 'input-error' : ''}
              aria-invalid={!!emailError}
              aria-describedby={emailError ? 'login-email-error' : undefined}
              autoFocus
            />
            {emailError && (
              <span id="login-email-error" className="error-message" role="alert">
                {emailError}
              </span>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="login-password">Password</label>
            <input
              id="login-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className={passwordError ? 'input-error' : ''}
              aria-invalid={!!passwordError}
              aria-describedby={passwordError ? 'login-password-error' : undefined}
            />
            {passwordError && (
              <span id="login-password-error" className="error-message" role="alert">
                {passwordError}
              </span>
            )}
          </div>
          {generalError && (
            <div className="error-message" role="alert">
              {generalError}
            </div>
          )}
          <button type="submit" className="btn-primary" disabled={loading}>
            {loading ? 'Signing in...' : 'Sign in'}
          </button>
        </form>
        <p className="auth-footer">
          Don't have an account? <Link to="/register">Create an account</Link>
        </p>
      </div>
    </main>
  );
}

/**
 * Register page component.
 *
 * Renders a centered card with username, email, and password inputs,
 * a password strength indicator, a "Register" button, and a link to sign in.
 * Handles client-side validation and shows inline error messages.
 *
 * On successful registration, auto-logs in and navigates to /tasks.
 */

import { useState, type FormEvent } from 'react';
import { useAuth } from '../hooks/useAuth';
import { useNavigate, Link } from 'react-router-dom';

/**
 * Calculate password strength score (0-5) and return a label + color.
 *
 * @param password - The password to evaluate.
 * @returns An object with score, label, and CSS color.
 */
function getPasswordStrength(password: string): { score: number; label: string; color: string } {
  if (!password) return { score: 0, label: '', color: '' };
  let score = 0;
  if (password.length >= 8) score++;
  if (password.length >= 12) score++;
  if (/[a-z]/.test(password) && /[A-Z]/.test(password)) score++;
  if (/\d/.test(password)) score++;
  if (/[^a-zA-Z0-9]/.test(password)) score++;

  if (score <= 1) return { score, label: 'Weak', color: 'var(--color-danger)' };
  if (score <= 3) return { score, label: 'Fair', color: '#e6a200' };
  if (score <= 4) return { score, label: 'Good', color: 'var(--color-success)' };
  return { score, label: 'Strong', color: 'var(--color-success)' };
}

export function Register() {
  const { register } = useAuth();
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [generalError, setGeneralError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    const newErrors: Record<string, string> = {};

    // Username validation
    if (!username.trim()) {
      newErrors.username = 'Username is required';
    } else if (username.length < 3) {
      newErrors.username = 'Username must be at least 3 characters';
    } else if (/\s/.test(username)) {
      newErrors.username = 'Username must not contain spaces';
    }

    // Email validation
    if (!email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      newErrors.email = 'Invalid email format';
    }

    // Password validation
    if (!password) {
      newErrors.password = 'Password is required';
    } else if (password.length < 8) {
      newErrors.password = 'Password must be at least 8 characters';
    }

    // Confirm password
    if (password !== confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match';
    }

    setErrors(newErrors);

    if (Object.keys(newErrors).length > 0) return;

    setLoading(true);
    try {
      await register(username, email, password);
      navigate('/tasks');
    } catch (err: unknown) {
      if (err && typeof err === 'object' && 'status' in err) {
        const apiErr = err as { status: number };
        if (apiErr.status === 409) {
          setGeneralError('Username or email already exists');
        } else {
          setGeneralError('Network error — please try again');
        }
      } else {
        setGeneralError('Network error — please try again');
      }
    } finally {
      setLoading(false);
    }
  };

  const strength = getPasswordStrength(password);

  return (
    <main className="auth-page">
      <div className="auth-card">
        <h1 className="auth-title">Task Management Dashboard</h1>
        <form onSubmit={handleSubmit} noValidate>
          <div className="form-group">
            <label htmlFor="register-username">Username</label>
            <input
              id="register-username"
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className={errors.username ? 'input-error' : ''}
              aria-invalid={!!errors.username}
              aria-describedby={errors.username ? 'register-username-error' : undefined}
              autoFocus
            />
            {errors.username && (
              <span id="register-username-error" className="error-message" role="alert">
                {errors.username}
              </span>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="register-email">Email</label>
            <input
              id="register-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className={errors.email ? 'input-error' : ''}
              aria-invalid={!!errors.email}
              aria-describedby={errors.email ? 'register-email-error' : undefined}
            />
            {errors.email && (
              <span id="register-email-error" className="error-message" role="alert">
                {errors.email}
              </span>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="register-password">Password</label>
            <input
              id="register-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className={errors.password ? 'input-error' : ''}
              aria-invalid={!!errors.password}
              aria-describedby={errors.password ? 'register-password-error' : undefined}
            />
            {errors.password && (
              <span id="register-password-error" className="error-message" role="alert">
                {errors.password}
              </span>
            )}
            {password && (
              <div className="password-strength" aria-live="polite">
                <div
                  className="password-strength-bar"
                  style={{ width: `${(strength.score / 5) * 100}%`, backgroundColor: strength.color }}
                />
                <span className="password-strength-label" style={{ color: strength.color }}>
                  {strength.label}
                </span>
              </div>
            )}
          </div>
          <div className="form-group">
            <label htmlFor="register-confirm-password">Confirm Password</label>
            <input
              id="register-confirm-password"
              type="password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className={errors.confirmPassword ? 'input-error' : ''}
              aria-invalid={!!errors.confirmPassword}
              aria-describedby={errors.confirmPassword ? 'register-confirm-error' : undefined}
            />
            {errors.confirmPassword && (
              <span id="register-confirm-error" className="error-message" role="alert">
                {errors.confirmPassword}
              </span>
            )}
          </div>
          {generalError && (
            <div className="error-message" role="alert">
              {generalError}
            </div>
          )}
          <button type="submit" className="btn-primary" disabled={loading}>
            {loading ? 'Creating account...' : 'Register'}
          </button>
        </form>
        <p className="auth-footer">
          Already have an account? <Link to="/">Sign in</Link>
        </p>
      </div>
    </main>
  );
}
